require_once dirname(__DIR__).'/includes/bootstrap.php';require_module('expenses');require_role(['Administrator','Finance Manager']);$id=(int)($_GET['id']??0);$token=$_GET['token']??'';if(!$token||!hash_equals(csrf_token(),$token)){http_response_code(419);exit('Invalid CSRF token.');}$s=db()->prepare('SELECT expense_code,status FROM expenses WHERE id=?');$s->execute([$id]);$expense=$s->fetch();if($expense && role_name()==='Finance Manager' && $expense['status']==='Approved'){flash('danger','Approved expenses can only be removed by an Administrator.');redirect('expenses/index.php');}$code=$expense['expense_code']??null;if($code){$rs=db()->prepare('SELECT stored_name FROM expense_receipts WHERE expense_id=?');$rs->execute([$id]);foreach($rs->fetchAll() as $f){@unlink(UPLOAD_PATH.'/'.$f['stored_name']);}db()->prepare("DELETE FROM approvals WHERE request_type='expense' AND request_id=?")->execute([$id]);db()->prepare('DELETE FROM expenses WHERE id=?')->execute([$id]);log_activity('DELETE','Expense','Deleted '.$code);flash('success','Expense deleted.');}redirect('expenses/index.php');
